/**
 * The paste-crypto CONTRACT test: the extension's wrap.js must decrypt
 * what the DEVICE side generates, byte-for-byte (L4 in docs/testing-plan.md).
 *
 * The vectors are the SAME fixed numbers DeviceWrapTest.kt pins on the
 * Android side — generated by scripts/gen_device_wrap_vectors.py
 * (Plan 2 rev 2, docs/extension-protocol.md). If either implementation
 * drifts (a constant, an AAD string, an HKDF step), this test or the
 * Kotlin one fails and the cross-language contract is broken.
 *
 * Run:  node extension/test/wrap_contract_test.mjs   (no deps, Node ≥ 19
 * for the global WebCrypto; the WebAuthn ceremony is bypassed via
 * unwrapPasteWithSeed — the shared decrypt path the self-test uses too).
 */
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";

const fail = (msg) => { console.error("FAIL: " + msg); process.exit(1); };
const ok = (msg) => console.log("  ok — " + msg);

// -- load wrap.js in a window shim (it targets the extension's window) ----
globalThis.window = {};
(0, eval)(readFileSync(new URL("../lib/wrap.js", import.meta.url), "utf8"));
const Lp = globalThis.window.LpWrap;
if (!Lp) fail("wrap.js did not install window.LpWrap");

// -- the committed vectors (scripts/gen_device_wrap_vectors.py output) -----
const PRF_OUT = new Uint8Array(32).map((_, i) => i);            // fake PRF out
const CRED_ID = new Uint8Array(32).map((_, i) => i + 32);       // fake credId
const SEED_SCALAR = 0xf749eebdc6474685e543a5af8ad872d272d5e0c562dd390f6870877e65ea8d1fn;
const KEY_ID = "72dbb7336c767800";
const RECORD = {"id":KEY_ID,"name":"vector-key-72db","credId":"ICEiIyQlJicoKSorLC0uLzAxMjM0NTY3ODk6Ozw9Pj8=","pub":"BCDrJBik1ztulBBV1OTCfTzv4jYxFNvAUgSJ+b/DFNJ9b9TamxTrUw6VRJ0kuRJPmNwspP6zsqXYrBwlSeVnocg=","keyId":KEY_ID,"added":1762500000,"salt":"q5oYXr3CRo9//Fj24tuSuUAAIqOrkORNlkzE7krAbYg=","wrapped":{"iv":"AAECAwQFBgcICQoL","ct":"cNRWuEn/6w2MxYuagfKPeiz4T1JW25sXSZ8Ggtf5md8D3B9yFzq9uSGKNefXXE1REV3pNZghf+eW8Y9UuhZ49ARVuuubi7W9w1dZgK51FgT7Kl3zU93xguKFvXhhJgCir8EGm7zrRMYgs1HrMB4mYe9k6kGIvX/viWNt2nEq3abQBVhJMXN+7CZiCTuou+uBOcbQmcCqwJsx8w=="}};
const WRAPPED_JSON = '{"v":1,"type":"offlinepass-wrap","payload":{"iv":"AQIDBAUGBwgJCgsM","ct":""},"targets":[{"keyId":"72dbb7336c767800","epk":"BJp4HKbQVafzDQyf+Hk2xzn2gW719ecrS5RkBLChqDsqwZ+EKUXqK/ZaoWSbKwL/eYVMjV7PzUA4YuipfqZsccE=","iv":"AAECAwQFBgcICQoL","ct":"sXfCVNY7rbqdxEnqunN4eaD0OihCLT8j8Jfg3LAE5zAvkfzbMM25St9DiJqNwMn3"},{"keyId":"ca2a4fe727faaecf","epk":"BD+Vxfbt9v4Fx+Jp70KOphYUv0VvAWjdtGQXDmt2h0kanE+acKIkUzswe8fPd2Zoj9I+rFB56aqI9SRLA9FElRA=","iv":"EBESExQVFhcYGRob","ct":"wE8HlyTS7wSSIrNijKCBP3d0+aspPxEyNOgneGJoVDCVRJ/IjHNiX7hWYk7IFZDf"}]}';
const EXPECTED = '{"itemId":"vec-item-0000","shareId":"local","data":{"type":"login","metadata":{"name":"Vector Test","itemUuid":"vec-item-0000"},"content":{"itemEmail":"","itemUsername":"vector","password":"s3cret-vector","urls":["https://example.test"],"totpUri":"","passkeys":[]}},"state":1}';

// -- helpers ---------------------------------------------------------------
const hex = (b) => Array.from(b, (c) => c.toString(16).padStart(2, "0")).join("");

/** The seed scalar's pkcs8 DER — built directly (deterministic ASN.1):
 *  node's createECDH can't derive a public point from a set private, and
 *  a JWK needs x/y, so the minimal PKCS#8 ECPrivateKey is constructed:
 *  SEQ { INT 1, OCTET d, [0] OID prime256v1 }. */
function seedPkcs8Der() {
  const D = Buffer.from(SEED_SCALAR.toString(16).padStart(64, "0"), "hex");
  const tlv = (tag, body) => {
    const len = body.length;
    const l = len < 0x80 ? Buffer.from([len])
      : len < 0x100 ? Buffer.from([0x81, len]) : Buffer.from([0x82, len >> 8, len & 0xff]);
    return Buffer.concat([Buffer.from([tag]), l, body]);
  };
  const INT = (b) => {
    let s = Buffer.from(b);
    if (s[0] & 0x80) s = Buffer.concat([Buffer.from([0]), s]);
    let i = 0; while (i < s.length - 1 && s[i] === 0 && !(s[i + 1] & 0x80)) i++;
    return tlv(0x02, s.subarray(i));
  };
  const inner = tlv(0x30, Buffer.concat([
    INT(Buffer.from([1])),  // the ECPrivateKey version
    tlv(0x04, D),
    tlv(0xa0, tlv(0x06, Buffer.from("2A8648CE3D030107", "hex")))  // prime256v1
  ]));
  return tlv(0x30, Buffer.concat([
    INT(Buffer.from([0])),
    tlv(0x30, Buffer.concat([
      tlv(0x06, Buffer.from("2A8648CE3D0201", "hex")),         // ecPublicKey
      tlv(0x06, Buffer.from("2A8648CE3D030107", "hex"))])),    // prime256v1
    tlv(0x04, inner)]));
}

/** The seed private key as a WebCrypto pkcs8-importable key (the thing
 *  unwrapSeed would return post-touch). */
async function seedPrivateKey() {
  return crypto.subtle.importKey("pkcs8", seedPkcs8Der(),
    { name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"]);
}

// -- 1. R1 identity: keyId derives from the credential ----------------------
if (await Lp.keyIdFor(CRED_ID) !== KEY_ID) fail("keyIdFor(credId) != " + KEY_ID);
ok("keyIdFor(credIdRaw) = " + KEY_ID + " (stable identity)");

// -- 2. the PRF salt derivation matches the device record -------------------
if (hex(await Lp.prfSalt(CRED_ID)) !==
    hex(Lp.unb64(RECORD.salt))) fail("prfSalt != the record's salt");
ok("prfSalt matches the device record's salt");

// -- 3. the seed-wrap layer: wrap.js primitives open the device's blob ------
{
  const saltRaw = Lp.unb64(RECORD.salt);
  const kek = await Lp.hkdf(PRF_OUT, saltRaw, Lp.SEED_INFO, 32);
  const plain = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: Lp.unb64(RECORD.wrapped.iv),
      additionalData: Lp.SEED_AAD },
    await crypto.subtle.importKey("raw", kek, "AES-GCM", false, ["decrypt"]),
    Lp.unb64(RECORD.wrapped.ct));
  // The unwrapped pkcs8 must decode to the seed scalar's own key. NOTE:
  // byte-level digest equality is wrong here — WebCrypto re-encodes pkcs8
  // (optional fields), so compare the KEY (the private scalar d).
  const imported = await crypto.subtle.importKey("pkcs8", plain,
    { name: "ECDH", namedCurve: "P-256" }, true, ["deriveBits"]);
  const jwk = await crypto.subtle.exportKey("jwk", imported);
  if (jwk.d !== Buffer.from(SEED_SCALAR.toString(16).padStart(64, "0"), "hex")
    .toString("base64url"))
    fail("seed unwrap produced a different key (d mismatch)");
  ok("wrap.js opens the device's wrapped seed (AES-GCM + HKDF + SEED_INFO/AAD) — same key material");
}

// -- 4. THE CONTRACT: unwrapPasteWithSeed decrypts the device's paste -------
{
  const got = await Lp.unwrapPasteWithSeed(await seedPrivateKey(), RECORD, WRAPPED_JSON);
  if (got !== EXPECTED) fail("paste plaintext mismatch:\n  got:  " + got + "\n  want: " + EXPECTED);
  ok("unwrapPasteWithSeed = the device's expected plaintext (the ECDH/HKDF/GCM chain, rev-2 targets[] format)");
}

// -- 5. negatives: a corrupted wrap must fail loudly ------------------------
{
  const w = JSON.parse(WRAPPED_JSON);
  const broken = JSON.stringify({ ...w, targets: w.targets.map((t) => t.keyId === KEY_ID
    ? { ...t, ct: Lp.b64(Lp.unb64(t.ct).map((b, i) => i === 0 ? b ^ 1 : b)) } : t) });
  let threw = false;
  try { await Lp.unwrapPasteWithSeed(await seedPrivateKey(), RECORD, broken); }
  catch (e) { threw = true; }
  if (!threw) fail("a tampered target ct decrypted without error");
  ok("tampered target ct throws (GCM auth)");

  const noTarget = JSON.stringify({ ...w, targets: [w.targets[1]] });
  threw = false;
  try { await Lp.unwrapPasteWithSeed(await seedPrivateKey(), RECORD, noTarget); }
  catch (e) { threw = true; }
  if (!threw) fail("a paste without this key's target decrypted without error");
  ok("paste without this key's target throws (named no-target error)");
}

// -- 6. TOTP parity (the same RFC 6238 vector the Android TotpTest pins) ----
{
  const realNow = Date.now;
  Date.now = () => 59_000; // RFC 6238's T=59
  try {
    const r = await Lp.totp("otpauth://totp/x?secret=GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ&digits=8");
    if (!r || r.code !== "94287082") fail("TOTP RFC 6238 vector: " + (r && r.code));
    ok("totp() = 94287082 (RFC 6238, SHA-1, 8 digits, T=59)");
  } finally { Date.now = realNow; }
}

console.log("\nALL CONTRACT TESTS PASSED");
